
-- ============================================================
-- Handoff Sante -- schema Supabase (migration depuis l'artefact Claude)
-- A coller et executer dans Supabase : SQL Editor > New query > Run
-- ============================================================

create table if not exists etablissements (
  id text primary key,
  nom text,
  ville text,
  region text,
  type text,
  adresse text,
  "createdAt" text,
  "nbServices" integer default 0
);

create table if not exists services (
  id text primary key,
  "etablissementId" text,
  "etablissementNom" text,
  "etablissementVille" text,
  "etablissementRegion" text,
  "etablissementType" text,
  nom text,
  "typeService" text,
  "nbLits" integer,
  "effectifsJour" jsonb,
  "effectifsNuit" jsonb,
  "nbSoignantsJour" integer,
  "nbSoignantsNuit" integer,
  "createdAt" text,
  "nbTemoignages" integer default 0,
  "avgCharge" numeric,
  "avgAmbiance" numeric,
  "avgDirection" numeric,
  "avgRemuneration" numeric,
  "avgGlobal" numeric,
  "avgNbPatients" numeric,
  "avgNbAs" numeric,
  "flagMaltraitance" integer default 0,
  "flagHarcelement" integer default 0,
  "flagRacisme" integer default 0,
  "aiSummary" jsonb,
  "aiSummaryAt" text,
  "aiSummaryBasedOn" integer default 0
);

create table if not exists temoignages (
  id text primary key,
  "serviceId" text,
  "serviceNom" text,
  "etablissementId" text,
  "etablissementNom" text,
  ville text,
  profession text,
  statut text,
  "dateMission" text,
  "noteCharge" numeric,
  "noteAmbiance" numeric,
  "noteDirection" numeric,
  "noteRemuneration" numeric,
  "nbPatientsCharge" numeric,
  "nbAsAvecToi" numeric,
  maltraitance boolean default false,
  "maltraitanceDetail" text,
  harcelement boolean default false,
  "harcelementDetail" text,
  racisme boolean default false,
  "racismeDetail" text,
  commentaire text,
  "createdAt" text,
  signalements integer default 0,
  "manageToken" text,
  "moderationVerified" boolean default false,
  "moderationVerifiedAt" text
);

create table if not exists suggestions (
  id text primary key,
  texte text,
  email text,
  statut text default 'nouvelle',
  "createdAt" text
);

create table if not exists "avisApp" (
  id text primary key,
  note numeric,
  commentaire text,
  "createdAt" text
);

create table if not exists reponses (
  id text primary key,
  "serviceId" text,
  "temoignageId" text,
  texte text,
  status text default 'en_attente',
  "createdAt" text
);

-- Row Level Security : ouvert (lecture + ecriture publique), comme la base
-- actuelle sur Claude qui n'a pas de vrais comptes utilisateurs. A durcir
-- plus tard si un vrai systeme de comptes est introduit.
alter table etablissements enable row level security;
alter table services enable row level security;
alter table temoignages enable row level security;
alter table suggestions enable row level security;
alter table "avisApp" enable row level security;
alter table reponses enable row level security;

drop policy if exists "public_all_etablissements" on etablissements;
create policy "public_all_etablissements" on etablissements for all using (true) with check (true);

drop policy if exists "public_all_services" on services;
create policy "public_all_services" on services for all using (true) with check (true);

drop policy if exists "public_all_temoignages" on temoignages;
create policy "public_all_temoignages" on temoignages for all using (true) with check (true);

drop policy if exists "public_all_suggestions" on suggestions;
create policy "public_all_suggestions" on suggestions for all using (true) with check (true);

drop policy if exists "public_all_avisApp" on "avisApp";
create policy "public_all_avisApp" on "avisApp" for all using (true) with check (true);

drop policy if exists "public_all_reponses" on reponses;
create policy "public_all_reponses" on reponses for all using (true) with check (true);

-- Realtime : necessaire pour que l'appli recoive les mises a jour en direct
alter publication supabase_realtime add table etablissements;
alter publication supabase_realtime add table services;
alter publication supabase_realtime add table temoignages;

